//! The shape a vehicle is, as convex hulls in chassis space.
//!
//! Generated by `tools/bake_collider` from `assets/models/warthog.glb` — **do not edit by hand**. Regenerate
//! it with:
//!
//! ```text
//! cargo run -p bake_collider -- bake assets/models/warthog.glb shared/src/vehicle_shape.rs
//! ```
//!
//! The server loads no assets at all — it has no renderer and no glTF loader — so the
//! shape has to travel as numbers rather than as a file, and shared code is where both
//! sides can see it. A model that may not be redistributed is a second reason and not
//! the load-bearing one. That is why this file is generated rather than loaded.
//!
//! Fired at from 20000 directions and compared against the model's own triangles, this shape
//! stops a shot a median of 0.9 cm short of the bodywork, 4.4 cm at the ninetieth
//! percentile and 18.6 cm at worst; 7 % of hits are more than 5 cm clear of the panel
//! and 0.0 % pass through a vehicle they visibly hit.

// Coordinates, not arithmetic: clippy reads a vertex that happens to land on 0.3010 as a
// fumbled `LOG10_2`, and says so once per vertex that does.
#![allow(clippy::approx_constant)]

/// Model units to metres, as this was baked. The game computes the same number from
/// `MODEL_LENGTH` and `half_extents`, and a test there checks the two agree.
pub const BUGGY_BAKE_SCALE: f32 = 2.45;
/// Metres the model's origin rose to become the chassis's, as this was baked.
pub const BUGGY_BAKE_LIFT: f32 = -0.283;

